// Admin links no longer expose contact names, phone numbers, IDs, or UTMs.
// A cryptographically authenticated opaque context is generated by the Worker.
export function supportContactParams(value=''){
  const query=value instanceof URLSearchParams?value:new URLSearchParams(
    String(value||'').replace(/^\?/,'')
  );
  const opaque=String(query.get('c')||'');
  return {opaque:/^ec1_[A-Za-z0-9_-]{35,16000}$/.test(opaque)?opaque:''};
}
export function supportContactAdminUrl({opaque=''}={}){
  return '/admin/mensagens'+(
    /^ec1_[A-Za-z0-9_-]{35,16000}$/.test(opaque)
      ?'?c='+encodeURIComponent(opaque):''
  );
}
